import java.util.*;
class DataLayouts {record Row(int id,int owner,int created,int amount){}record Visit(int owner,int depth){}
static List<Row> query(List<Row>rows,int[][]friends,int owner,int depth,int minCreated,int maxCreated,int minAmount,String model,boolean ownerIndex){Map<Integer,List<Row>>groups=new HashMap<>();Map<Integer,List<Integer>>adj=new HashMap<>();Map<Integer,Row>kv=new HashMap<>();for(Row r:rows){groups.computeIfAbsent(r.owner(),k->new ArrayList<>()).add(r);kv.put(r.id(),r);}groups.values().forEach(list->list.sort(Comparator.comparingInt(Row::created).thenComparingInt(Row::id)));for(int[]e:friends)adj.computeIfAbsent(e[0],k->new ArrayList<>()).add(e[1]);Set<Integer>owners=new HashSet<>();owners.add(owner);List<Visit>queue=new ArrayList<>(List.of(new Visit(owner,0)));
for(int head=0;head<queue.size();head++){Visit v=queue.get(head);if(v.depth()>=depth)continue;List<Integer>neighbors=new ArrayList<>();if(model.equals("graph"))neighbors.addAll(adj.getOrDefault(v.owner(),List.of()));else for(int[]e:friends)if(e[0]==v.owner())neighbors.add(e[1]);for(int n:neighbors)if(owners.add(n))queue.add(new Visit(n,v.depth()+1));}
List<Row>candidates=new ArrayList<>();if(List.of("document","graph","wide-column").contains(model)||ownerIndex){for(int o:owners){List<Row>group=groups.getOrDefault(o,List.of());int start=0,end=group.size();if(model.equals("wide-column")){int lo=0,hi=end;while(lo<hi){int mid=(lo+hi)/2;if(group.get(mid).created()<minCreated)lo=mid+1;else hi=mid;}start=lo;hi=end;while(lo<hi){int mid=(lo+hi)/2;if(group.get(mid).created()<=maxCreated)lo=mid+1;else hi=mid;}end=lo;}for(int i=start;i<end;i++){Row r=group.get(i);candidates.add(model.equals("key-value")?kv.get(r.id()):r);}}}else candidates.addAll(rows);
return candidates.stream().filter(r->owners.contains(r.owner())&&r.created()>=minCreated&&r.created()<=maxCreated&&r.amount()>=minAmount).sorted(Comparator.comparingInt(Row::id)).toList();}}
